class Solution:
    def firstPrincipalComponent(self, points: List[List[float]], start: List[float]) -> List[float]:
        n, d = len(points), len(points[0])
        mean = [sum(p[j] for p in points) / n for j in range(d)]
        centred = [[p[j] - mean[j] for j in range(d)] for p in points]
        cov = [[0.0] * d for _ in range(d)]
        for row in centred:
            for i in range(d):
                for j in range(i, d):
                    cov[i][j] += row[i] * row[j]
        for i in range(d):
            for j in range(i, d):
                cov[i][j] /= (n - 1)
                cov[j][i] = cov[i][j]

        def normalise(vec: List[float]) -> List[float]:
            norm = math.sqrt(sum(x * x for x in vec))
            return [x / norm for x in vec]

        v = normalise([float(x) for x in start])
        for _ in range(500):
            w = [sum(cov[i][j] * v[j] for j in range(d)) for i in range(d)]
            v = normalise(w)
        for x in v:
            if abs(x) > 1e-12:
                if x < 0:
                    v = [-y for y in v]
                break
        return v

